struct Point { long long x, y; };
Point sub(Point a, Point b)  { return {a.x - b.x, a.y - b.y}; }
long long dot(Point a, Point b)   { return a.x * b.x + a.y * b.y; }
long long cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }

